package com.kafka.backend.naverarchive;

import static org.assertj.core.api.Assertions.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.Flow;
import org.junit.jupiter.api.Test;

class NaverRssFeedTest {
 static String item(String id,String date,String description){return "<item><guid>https://blog.naver.com/yozo990/"+id+"</guid><link>https://blog.naver.com/yozo990/"+id+"?fromRss=true</link><title>SYNTHETIC 한글</title><category>분류</category><pubDate>"+date+"</pubDate><description><![CDATA["+description+"]]></description></item>";}
 static byte[] xml(String items){return ("<?xml version='1.0' encoding='UTF-8'?><rss version='2.0'><channel><link>https://blog.naver.com/yozo990?fromRss=true</link>"+items+"</channel></rss>").getBytes(StandardCharsets.UTF_8);}
 static NaverRssFeed.Feed parse(String item){return NaverRssFeed.parse(xml(item));}
 @Test void koreanTimezoneAndExcerptsAreAlwaysUnverified(){var feed=parse(item("224481843682","Wed, 18 Nov 2026 12:40:38 +0900","<p>첫 줄\n\n  둘째 줄...</p><script>evil()</script><img src='https://invalid.example/a.png'>"));var e=feed.items().getFirst();assertThat(e.id()).isEqualTo("224481843682");assertThat(e.published()).isEqualTo(Instant.parse("2026-11-18T03:40:38Z"));assertThat(e.excerpt()).contains("첫 줄","둘째 줄...").doesNotContain("evil()");assertThat(e.truncated()).isTrue();assertThat(e.media()).isEqualTo(1);assertThat(feed.hash()).hasSize(64);assertThat(e.url()).isEqualTo("https://blog.naver.com/yozo990/224481843682");}
 @Test void absentDateAndGuidFallbackRetainItem(){var e=parse(item("123","unknown","body").replace("<guid>https://blog.naver.com/yozo990/123</guid>","")).items().getFirst();assertThat(e.published()).isNull();assertThat(e.id()).isEqualTo("123");}
 @Test void fullContentTagDoesNotUpgradeExcerpt(){var e=parse(item("123","","short...").replace("</item>","<content:encoded xmlns:content='http://purl.org/rss/1.0/modules/content/'><![CDATA[full text]]></content:encoded></item>")).items().getFirst();assertThat(e.excerpt()).isEqualTo("short...");}
 @Test void hostileOrContradictoryLinksAreNeverFollowedOrAccepted(){for(String url:List.of("http://blog.naver.com/yozo990/1","https://evil.example/yozo990/1","https://blog.naver.com/other/1","https://blog.naver.com:443/yozo990/1","https://user@blog.naver.com/yozo990/1","https://blog.naver.com/yozo990/1#x"))assertThat(NaverRssFeed.id(url)).isNull();var valid=item("1","","a");var bad=item("2","","b").replace("https://blog.naver.com/yozo990/2?fromRss=true","https://evil.example/2");assertThat(parse(valid+bad).invalid()).isEqualTo(1);assertThat(parse(valid+item("2","","b").replace("/2?fromRss", "/3?fromRss")).invalid()).isEqualTo(1);}
 @Test void duplicateIdInvalidXmlEntitiesAndBoundsFailClosed(){assertThatThrownBy(()->parse(item("1","","a")+item("1","","a"))).hasMessage("DUPLICATE_FEED_ID");assertThatThrownBy(()->NaverRssFeed.parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///C:/private'>]><rss>&x;</rss>".getBytes(StandardCharsets.UTF_8))).hasMessage("INVALID_XML");assertThatThrownBy(()->NaverRssFeed.parse(new byte[NaverRssFeed.MAX_BYTES+1])).hasMessage("PAYLOAD_TOO_LARGE");assertThatThrownBy(()->parse(item("1","","a").repeat(101))).hasMessage("TOO_MANY_ITEMS");assertThatThrownBy(()->NaverRssFeed.parse("<html>blocked</html>".getBytes(StandardCharsets.UTF_8))).hasMessage("INVALID_RSS");}
 @Test void feedReorderDoesNotChangeIdentityOrItemFingerprint(){var a=item("1","","first");var b=item("2","","second");var one=parse(a+b);var two=parse(b+a);assertThat(one.items().getFirst().hash()).isEqualTo(two.items().getLast().hash());assertThat(one.hash()).isNotEqualTo(two.hash());}
 @Test void httpFailuresStopAndHonorRetryAfter(){Instant now=Instant.parse("2026-11-21T00:00:00Z");for(int code:List.of(301,302,401,403)){try{NaverRssClient.checkStatus(code,"",now);fail("expected refusal");}catch(NaverRssFeed.Failure e){assertThat(e.blocked).isTrue();}}try{NaverRssClient.checkStatus(429,"7200",now);fail("expected rate limit");}catch(NaverRssFeed.Failure e){assertThat(e.retryAt).isEqualTo(now.plusSeconds(7200));assertThat(e.blocked).isFalse();}assertThat(NaverRssClient.retryAfter("Sat, 21 Nov 2026 02:00:00 GMT",now)).isEqualTo(now.plusSeconds(7200));assertThat(NaverRssClient.retryAfter("bad",now)).isNull();assertThat(NaverRssClient.retryAfter(Long.toString(Long.MAX_VALUE),now)).isEqualTo(Instant.parse("9999-12-31T00:00:00Z"));assertThatThrownBy(()->NaverRssClient.checkStatus(503,"",now)).hasMessage("SOURCE_UNAVAILABLE");}
 @Test void oversizedStreamingBodyCancelsBeforeCompletion(){var body=NaverRssClient.bounded();boolean[] cancelled={false};body.onSubscribe(new Flow.Subscription(){public void request(long n){}public void cancel(){cancelled[0]=true;}});body.onNext(List.of(ByteBuffer.wrap(new byte[NaverRssFeed.MAX_BYTES+1])));assertThat(cancelled[0]).isTrue();assertThatThrownBy(()->body.getBody().toCompletableFuture().join()).hasCauseInstanceOf(NaverRssFeed.Failure.class);}
 @Test void refusalHeadersTakePrecedenceOverAnyBody(){for(int code:List.of(403,429,302)){var info=new java.net.http.HttpResponse.ResponseInfo(){public int statusCode(){return code;}public java.net.http.HttpHeaders headers(){return java.net.http.HttpHeaders.of(Map.of("Retry-After",List.of("7200"),"Content-Type",List.of("text/html")),(a,b)->true);}public java.net.http.HttpClient.Version version(){return java.net.http.HttpClient.Version.HTTP_1_1;}};try{NaverRssClient.responseBody(info);fail("body must never start");}catch(NaverRssFeed.Failure e){assertThat(e.category).isEqualTo(code==403?"POLICY_BLOCKED":code==429?"RATE_LIMITED":"REDIRECT_DENIED");if(code==429)assertThat(e.retryAt).isAfter(Instant.now().plusSeconds(7190));}}}
}
